src='''import numpy as np, time

def softmax(a):
 a=a-a.max(-1,keepdims=True); e=np.exp(a); return e/e.sum(-1,keepdims=True)

def predict(x,init,A,B):
 n,T=x.shape; q=np.tile(init,(n,1)); out=np.empty((n,T,B.shape[1]))
 for t in range(T):
  out[:,t]=q@B
  w=q*B[:,x[:,t]].T; q=(w/w.sum(1,keepdims=True))@A
 return out

def fit(x,target,K,steps=1500,seed=1,lr=.035,initial=None,report=False):
 rng=np.random.default_rng(seed); n,T=x.shape; V=target.shape[2]
 if initial is None:
  pars=[np.zeros(K),rng.normal(0,.5,(K,K))+np.eye(K)*2,rng.normal(0,.7,(K,V))+np.log(target.mean((0,1)))]
 else: pars=[np.log(np.maximum(a,1e-8)) for a in initial]
 m=[np.zeros_like(a) for a in pars]; vv=[np.zeros_like(a) for a in pars]; scale=1/(n*T)
 for step in range(1,steps+1):
  init,A,B=map(softmax,pars); q=np.tile(init,(n,1)); qs=[]; rs=[]; norms=[]; pred=[]
  for t in range(T):
   qs.append(q); pred.append(q@B); w=q*B[:,x[:,t]].T; norm=w.sum(1,keepdims=True); r=w/norm; rs.append(r); norms.append(norm); q=r@A
  gA=np.zeros_like(A); gB=np.zeros_like(B); dq=np.zeros((n,K)); loss=0
  for t in reversed(range(T)):
   gp=-target[:,t]/np.maximum(pred[t],1e-12)*scale
   gB+=qs[t].T@gp
   if t<T-1:
    gA+=rs[t].T@dq; dr=dq@A.T; dw=(dr-(dr*rs[t]).sum(1,keepdims=True))/norms[t]
    gb=dw*qs[t]
    for k in range(K): np.add.at(gB[k],x[:,t],gb[:,k])
    dq=gp@B.T+dw*B[:,x[:,t]].T
   else: dq=gp@B.T
  gi=dq.sum(0); grads=[gi,gA,gB]
  for j,(par,g,prob) in enumerate(zip(pars,grads,[init,A,B])):
   g=prob*(g-(g*prob).sum(-1,keepdims=True)); m[j]=.9*m[j]+.1*g; vv[j]=.999*vv[j]+.001*g*g
   rate=lr*(.3+.7*(1-step/steps))
   par-=rate*(m[j]/(1-.9**step))/(np.sqrt(vv[j]/(1-.999**step))+1e-8)
  if report and (step%500==0 or step==1):
   predarr=np.stack(pred,axis=1); print(step,'KL',np.mean(np.sum(target*np.log(target/np.maximum(predarr,1e-12)),axis=2)),flush=True)
 return tuple(map(softmax,pars))

def metrics(target,p):
 return dict(kl=float(np.mean(np.sum(target*np.log(target/np.maximum(p,1e-12)),axis=2))),rmse=float(np.sqrt(((target-p)**2).mean())))
'''
